## 前端：棋盘渲染和键盘输入

数独棋盘的渲染用 CSS Grid：

```html
<!-- 9×9 棋盘 -->
<div class="sudoku-board" style="width: min(85vmin, 500px); height: min(85vmin, 500px);">
  @for (cell of board(); track $index) {
    <div
      class="sudoku-cell"
      [class.selected]="isSelected($index)"
      [class.conflict]="isConflict($index)"
      [class.given]="isGiven($index)"
      (click)="selectCell($index)"
    >
      {{ cell !== 0 ? cell : '' }}
    </div>
  }
</div>
```

键盘输入处理：

```typescript
@HostListener('document:keydown', ['$event'])
onKeyDown(event: KeyboardEvent) {
    const selected = this.selected();  // 当前选中的格子索引
    if (selected === null) return;

    const num = parseInt(event.key);
    if (num >= 1 && num <= 9) {
        this.store.fillCell(selected, num);
    } else if (event.key === 'Backspace' || event.key === 'Delete') {
        this.store.fillCell(selected, 0);  // 清空
    } else if (event.key === 'ArrowUp')    { this.moveSelection(-9); }
    else if (event.key === 'ArrowDown')   { this.moveSelection(9);  }
    else if (event.key === 'ArrowLeft')   { this.moveSelection(-1); }
    else if (event.key === 'ArrowRight')  { this.moveSelection(1);  }
}
```

